// Build tooling. Compiles spec/schemas/*.json to standalone validators with ajv.
// Run with `pnpm --filter @tcg-gauntlet/engine gen:schemas`. The output is
// committed, and CI regenerates it and fails on any diff. The engine imports only
// the generated file at run time, never ajv.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import Ajv2020Module from "ajv/dist/2020.js";
import standaloneModule from "ajv/dist/standalone/index.js";

// ajv is CommonJS. Under NodeNext, TypeScript types a default import as the whole
// module namespace, while Node gives module.exports, which is the class (or the
// function) itself.
const Ajv2020 = Ajv2020Module as unknown as typeof Ajv2020Module.default;
const standaloneCode =
  standaloneModule as unknown as typeof standaloneModule.default;

const root = fileURLToPath(new URL("../../..", import.meta.url));
const outDir = fileURLToPath(new URL("../src/generated/", import.meta.url));

const schemas = [
  ["validateDeckFrontMatter", "deck-front-matter.v1.schema.json"],
  ["validateGauntlet", "gauntlet.v1.schema.json"],
  ["validateFormatDefinition", "format-definition.v1.schema.json"],
] as const;

const ajv = new Ajv2020({
  code: { source: true, esm: true },
  allErrors: true,
  strict: true,
});

const refs: Record<string, string> = {};
for (const [exportName, file] of schemas) {
  const schema = JSON.parse(
    readFileSync(`${root}spec/schemas/${file}`, "utf8"),
  ) as { $id: string };
  ajv.addSchema(schema);
  refs[exportName] = schema.$id;
}

let code = standaloneCode(ajv, refs);

// The generated code imports ajv's small runtime helpers. Inline them, so that the
// engine never imports ajv at run time.
const helpers: Record<string, string> = {
  "ajv/dist/runtime/ucs2length": `function ucs2length(str) {
  const len = str.length;
  let length = 0;
  let pos = 0;
  let value;
  while (pos < len) {
    length++;
    value = str.charCodeAt(pos++);
    if (value >= 0xd800 && value <= 0xdbff && pos < len) {
      value = str.charCodeAt(pos);
      if ((value & 0xfc00) === 0xdc00) pos++;
    }
  }
  return length;
}`,
  "ajv/dist/runtime/equal": `function equal(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}`,
};
const requireRe =
  /const (\w+) = require\("(ajv\/dist\/runtime\/[a-z0-9]+)"\)\.default;?\n?/g;
code = code.replace(requireRe, (_m, name: string, mod: string) => {
  const body = helpers[mod];
  if (body === undefined)
    throw new Error(`Unhandled ajv runtime helper: ${mod}`);
  return `const ${name} = (${body});\n`;
});
if (/\brequire\(|from "ajv/.test(code)) {
  throw new Error("Generated validators still depend on ajv");
}

const banner = `// Generated by scripts/compile-schemas.ts from spec/schemas/*.json. Do not edit.\n// Regenerate with: pnpm --filter @tcg-gauntlet/engine gen:schemas\n`;
writeFileSync(`${outDir}validators.js`, banner + code);

const dts = `${banner}export interface ValidationError {
  instancePath: string;
  schemaPath: string;
  keyword: string;
  params: Record<string, unknown>;
  message?: string;
}

export interface Validator {
  (data: unknown): boolean;
  errors?: ValidationError[] | null;
}

${schemas.map(([name]) => `export const ${name}: Validator;`).join("\n")}
`;
writeFileSync(`${outDir}validators.d.ts`, dts);
